options(digits = 17, warn = 1, useFancyQuotes = FALSE)
rc_lines <- character(0)
rc_num <- function(tag, v) {
  rc_lines <<- c(rc_lines, sprintf("%s|v|%s", tag,
    paste(sprintf("%.17g", ifelse(is.na(v), NaN, v)), collapse = " ")))
}
rc_chr <- function(tag, v) {
  rc_lines <<- c(rc_lines, sprintf("%s|v|%s", tag, paste(v, collapse = "\x1f")))
}

# --- replacement: hand ---
x <- matrix(c(0, 2, 8, 4, 0, 6), nrow = 2, ncol = 3, byrow = TRUE)
rc_err <- NA_character_
tryCatch({da_zr_x <- x
da_zr_delta <- 0.65
da_zr_threshold <- 0.5
da_zr_out <- as.matrix(cmultRepl(
  as.data.frame(da_zr_x), label = 0, method = "CZM", output = "prop",
  frac = da_zr_delta, threshold = da_zr_threshold, adjust = TRUE,
  z.warning = 1, z.delete = FALSE, suppress.print = TRUE))

}, error = function(e) rc_err <<- conditionMessage(e))
rc_chr("repl.hand.error", ifelse(is.na(rc_err), "none", rc_err))
if (is.na(rc_err)) {
  rc_num("repl.hand.out", as.vector(t(da_zr_out)))
  rc_num("repl.hand.mass", rowSums(ifelse(x == 0, da_zr_out, 0)))
  rc_num("repl.hand.rest", 1 - rowSums(da_zr_out))
  rc_num("repl.hand.minobs", min(da_zr_out[x > 0]))
  rc_chr("repl.hand.positive", ifelse(all(da_zr_out[x > 0] > 0), "yes", "no"))
}

