# --- full chain: effect ---
x <- matrix(c(7, 32, 81, 17, 18, 50, 1, 44, 22, 12, 6, 65, 10, 43, 39, 3, 27, 71, 15, 39, 59, 14, 14, 10, 6, 30, 45, 11, 49, 73, 15, 23, 54, 9, 35, 31, 52, 14, 4, 18, 35, 8, 40, 27, 8, 57, 49, 2, 25, 6, 6, 58, 32, 1, 8, 44, 5, 43, 23, 9, 65, 43, 1, 31, 30, 7, 47, 18, 3, 36, 39, 6), nrow = 24, ncol = 3, byrow = TRUE)
z <- if (any(x == 0)) {
da_zr_x <- x
da_zr_delta <- 0.65
da_zr_threshold <- 0.5
da_zr_out <- as.matrix(cmultRepl(
  as.data.frame(da_zr_x), label = 0, method = "CZM", output = "prop",
  frac = da_zr_delta, threshold = da_zr_threshold, adjust = TRUE,
  z.warning = 1, z.delete = FALSE, suppress.print = TRUE))

  sweep(log(da_zr_out), 1, rowMeans(log(da_zr_out)), "-")
} else {
  da_zr_out <- as.matrix(x / rowSums(as.matrix(x)))
  sweep(log(da_zr_out), 1, rowMeans(log(da_zr_out)), "-")
}

